<?php
require __DIR__.'/bootstrap.php'; require __DIR__.'/lib/CareView.php';
$auth->requireAbility('secretary'); $church=$auth->currentChurch(); if(!$church) redirect('/logout.php');
$care=new ChurchCare($pdo,(string)$church['id']); $error=null; $edit=[];
$selected=trim((string)($_GET['department']??''));
if($_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check(); try {
        if(in_array($_POST['action']??'',['enroll','remove'],true)) { $care->enrollment($_POST); $selected=ChurchCare::text($_POST,'department_id',36,true); }
        else $selected=$care->department($_POST);
        flash('success','Departamento atualizado.'); redirect('/departments.php?department='.rawurlencode($selected));
    } catch(Throwable $e) { $error=care_error($e); }
}
if($selected!=='') { try { $edit=$care->owned('ministry_departments',$selected); } catch(Throwable $e) { $error=care_error($e); $selected=''; } }
$departments=$care->all('SELECT d.*,(SELECT COUNT(*) FROM ministry_members mm WHERE mm.department_id=d.id AND mm.church_id=d.church_id) total FROM ministry_departments d WHERE d.church_id=? ORDER BY d.active DESC,d.name');
$enrolled=$selected!==''?$care->all('SELECT m.id,m.name,m.phone,mm.joined_on FROM ministry_members mm INNER JOIN members m ON m.id=mm.member_id AND m.church_id=mm.church_id WHERE mm.church_id=? AND mm.department_id=? ORDER BY m.name',[$selected]):[];
View::header('Departamentos',$auth,'departments.php'); care_heading('Departamentos e ministérios','Organize Kids, jovens, louvor, EBD, casais, discipulado e outros grupos com seus próprios líderes e participantes.'); care_notice($error);
?>
<div class="grid two-col"><section class="card card-pad"><h2>Departamentos</h2><p class="muted">O campo Departamento dos cadastros antigos continua preservado. Os vínculos abaixo permitem participar de vários ministérios.</p><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Líder</th><th>Participantes</th><th>Situação</th></tr></thead><tbody><?php if(!$departments):?><tr><td colspan="4">Cadastre o primeiro departamento ao lado.</td></tr><?php endif?><?php foreach($departments as $d):?><tr><td><a href="?department=<?=e($d['id'])?>"><?=e($d['name'])?></a><div><?=e($d['meeting_info'])?></div></td><td><?=e($d['leader'])?></td><td><?=(int)$d['total']?></td><td><?=$d['active']?'Ativo':'Inativo'?></td></tr><?php endforeach?></tbody></table></div>
<?php if($edit):?><h2>Participantes · <?=e($edit['name'])?></h2><div class="table-wrap"><table class="table"><thead><tr><th>Membro</th><th>Telefone</th><th class="no-print"></th></tr></thead><tbody><?php if(!$enrolled):?><tr><td colspan="3">Nenhum participante vinculado.</td></tr><?php endif?><?php foreach($enrolled as $m):?><tr><td><a href="member-profile.php?id=<?=e($m['id'])?>"><?=e($m['name'])?></a></td><td><?=e($m['phone'])?></td><td class="no-print"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove"><input type="hidden" name="department_id" value="<?=e($selected)?>"><input type="hidden" name="member_id" value="<?=e($m['id'])?>"><button class="btn btn-light">Desvincular</button></form></td></tr><?php endforeach?></tbody></table></div><form method="post" class="no-print"><?=csrf_field()?><input type="hidden" name="action" value="enroll"><input type="hidden" name="department_id" value="<?=e($selected)?>"><?php care_field('member_id','Adicionar participante','','select',true,care_member_options($care));?><button class="btn btn-primary">Vincular membro</button></form><?php endif?></section>
<section data-registry-form="departments" class="card card-pad no-print"><h2><?=$edit?'Editar departamento':'Novo departamento'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><?php care_field('name','Nome',$edit['name']??'','text',true); care_field('leader','Líder responsável',$edit['leader']??''); care_field('meeting_info','Dia, horário e local dos encontros',$edit['meeting_info']??'');?></div><p><label><input type="checkbox" name="active" value="1" <?=!$edit||$edit['active']?'checked':''?>> Departamento ativo</label></p><button class="btn btn-primary">Salvar departamento</button> <a class="btn btn-light" href="departments.php">Novo / limpar</a></form></section></div>
<?php View::footer();
